    under: { color: 0x15171b, collar: 0.500, hem: -0.10 },
    bottom: { color: 0x1b1d21, hem: 0.99, tears: 0.03 },
    shoes: { kind: 'sneaker', color: 0xe2e0da, sole: 0xa8323c },
