    grip: { x: -0.046, y: -0.0170, len: 0.094, rake: 0.58,
      deep: 1.02, wide: 0.82, e: 0.74, checkN: [6, 10] },
    mag: { x: -0.046, y: -0.0190, len: 0.086, r: 0.030 },
