    barrel: { r0: 0.0165, r1: 0.0148, bore: 0.0064, step: 0.360, brake: null },
    rec: { rear: -0.150, front: 0.100, up: 0.0240, down: 0.0215, w: 0.0190, e: 3.6 },
    hg: { kind: 'poly', x0: 0.120, x1: 0.360, r: 0.0270, w: 0.0260 },
