    grip: { x: -0.096, y: -0.0180, len: 0.114, rake: 0.30, deep: 1.14, e: 1.0 },
    stock: { kind: 'wood', butt: -0.375, comb: 0.0230, drop: 0.0330, w: 0.0215 },
