    if (gun.cover) gun.cover.setRotation([0, 0, -(gun.coverArc || 62) * beltCover(reload)]);
    if (gun.belt) gun.belt.setPosition([0, 0, -(gun.linkPitch || 0.016) * ((s.rounds || 0) % 4)]);
