    handL: { keys: [[0, 4, 0, -3], [0.5, -2, 0, 2], [1, 4, 0, -3]] },
    handR: { keys: [[0, -3, 0, 2], [0.5, 5, 0, -3], [1, -3, 0, 2]] },
